import {orderKind,isTestOrder,nextStep,dateTime,paymentLabel,orderLabels} from './admin-order-state.mjs';
import {mockupsForCheckout,mockupsForPfOrder,appendMockupOverview} from './admin-mockups.mjs?v=4';
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!=null)n.textContent=text;if(cls)n.className=cls;return n;};
export function isUnfinishedPayment(checkout,pfs=[]){return !pfs.length&&!checkout.pfOrderIds?.length&&!checkout.paidAt&&['prepared','payment_setup','payment_setup_uncertain','awaiting_payment','expired','payment_failed','cancelled'].includes(checkout.status);}
export function orderList(orders,checkouts){const panel=el('section',null,'order-workspace'),tools=el('div',null,'order-tools'),search=el('input'),tests=el('input'),label=el('label'),list=el('div');search.type='search';search.placeholder='Søg kunde, produkt eller ordrenummer';search.setAttribute('aria-label','Søg ordrer');tests.type='checkbox';label.append(tests,document.createTextNode('Vis testordrer'));tools.append(search,label);panel.append(tools,list);const records=[...checkouts.map(c=>({checkout:c,pfs:orders.filter(o=>o.checkoutId===c.id)})),...orders.filter(o=>!checkouts.some(c=>c.id===o.checkoutId)).map(o=>({pfs:[o]}))].sort((a,b)=>String(b.checkout?.createdAt||b.pfs[0]?.createdAt).localeCompare(String(a.checkout?.createdAt||a.pfs[0]?.createdAt)));
function render(){list.replaceChildren();let count=0;const attempts=el('details',null,'orders-secondary'),attemptList=el('div');let attemptCount=0;for(const r of records){const c=r.checkout,o=r.pfs[0]||{},kind=orderKind(o,c),shipping=c?.shipping||o.shipping||{},lines=c?.lines||o.lines||[],query=[c?.id,o.purchaseOrderNumber,...r.pfs.map(p=>p.pfOrderNumber),shipping.name,shipping.email,...lines.flatMap(l=>[l.sku,l.productId,c?.productNames?.[l.productId]])].join(' ').toLocaleLowerCase('da');if((!tests.checked&&isTestOrder(o,c))||!query.includes(search.value.trim().toLocaleLowerCase('da')))continue;if(c&&isUnfinishedPayment(c,r.pfs)){attemptCount++;const row=el('article',null,'order-card'),open=el('button','Åbn betalingsdetaljer');open.type='button';open.onclick=()=>{const target=document.getElementById('checkout-'+c.id);if(!target)return;for(let node=target;node;node=node.parentElement)if(node.tagName==='DETAILS')node.open=true;target.scrollIntoView({block:'start',behavior:'smooth'});};row.append(el('strong',shipping.name||shipping.email||c.id),el('p',dateTime(c.createdAt)+' · '+paymentLabel(c)),el('small',c.status==='cancelled'?'Annulleret betalingsforsøg · historik bevaret':'Uafsluttet betalingsforsøg · ingen PF-ordre'),open);attemptList.append(row);continue;}count++;const row=el('article',null,'order-summary-card'),gallery=el('div'),info=el('div'),state=el('div');appendMockupOverview(gallery,c?mockupsForCheckout(c):mockupsForPfOrder(null,o),{decorated:lines.some(l=>l.decorations?.length)});info.append(el('span',kind,'pill'),el('h3',shipping.name||shipping.email||'Kunde ikke oplyst'),el('small',dateTime(c?.createdAt||o.createdAt)));for(const l of lines)info.append(el('p',`${l.quantity} stk. · ${c?.productNames?.[l.productId]||l.productName||l.productId} · ${l.sku}`));const ref=el('small','Reference: '+(c?.id||o.purchaseOrderNumber));ref.className='order-reference';info.append(ref);state.append(el('strong',paymentLabel(c)));if(Number.isFinite(c?.totalIncVat))state.append(el('p',(c.totalIncVat/100).toLocaleString('da-DK',{style:'currency',currency:'DKK'})+' inkl. moms'));for(const p of r.pfs){const a=el('a','Åbn ordre '+(p.pfOrderNumber||'→'),'action light');a.href='/admin/pf-orders#order='+encodeURIComponent(p.id);state.append(el('p',orderLabels[p.status]||p.status),el('small',nextStep(p).join(' · ')),a);}if(!r.pfs.length)state.append(el('p',c?.pfHandoff?.reason||'Ingen PF-ordre tilknyttet. Se betalingsdetaljer nedenfor.'));row.append(gallery,info,state);list.append(row);}if(!count)list.append(el('p','Ingen ordrer i denne visning. Slå “Vis testordrer” til for at se jeres tests.','muted'));if(attemptCount){attempts.append(el('summary',`Betalingsforsøg · ikke bestilte ordrer (${attemptCount})`),attemptList);list.append(attempts);}}search.oninput=tests.onchange=render;render();return panel;}
